using UnityEngine; using UnityEngine.SceneManagement; public class DeathMenu : MonoBehaviour { public GameObject deathUI; void Start() { Time.timeScale = 1f; deathUI.SetActive(true); } public void Restart() { Time.timeScale = 1f; SceneManager.LoadScene("BasicScene"); } public void MainMenu() { Time.timeScale = 1f; SceneManager.LoadScene("MainMenuScene"); } public void ShowDeath() { deathUI.SetActive(true); Time.timeScale = 0f; } }